import{_ as i,C as n,o as r,c as d,ao as s,j as a,a as l,E as o,w as c}from"./chunks/framework.B2J7Oa2h.js";const v=JSON.parse('{"title":"Package","description":"","frontmatter":{},"headers":[],"relativePath":"reference/package.md","filePath":"reference/package.md","lastUpdated":null}'),p={name:"reference/package.md"},u={class:"jldocstring custom-block",open:""};function m(h,e,g,f,b,k){const t=n("Badge");return r(),d("div",null,[e[4]||(e[4]=s('<h1 id="Package" tabindex="-1">Package <a class="header-anchor" href="#Package" aria-label="Permalink to &quot;Package {#Package}&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">Start here</p><p><code>DRModels</code> is the package module. For fitting choices, begin with <a href="./../capabilities">What can I fit today?</a>; for runnable syntax, use <a href="./../getting-started">Getting started</a>. This page documents the module overview rather than making a package-wide performance claim.</p></div>',2)),a("details",u,[a("summary",null,[e[0]||(e[0]=a("a",{id:"DRModels",href:"#DRModels"},[a("span",{class:"jlbinding"},"DRModels")],-1)),e[1]||(e[1]=l()),o(t,{type:"info",class:"jlObjectType jlModule",text:"Module"})]),e[3]||(e[3]=s('<div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DRModels</span></span></code></pre></div><p><code>DRModels.jl</code> fits distributional regression models for continuous, count, proportion, and ordered responses. It provides univariate routes and selected bivariate routes. Random effects and dependence from phylogenies, spatial coordinates, pedigrees, and supplied matrices are available on the combinations listed in the capability guide. The R package <strong>drmTMB</strong> can call selected routes through its optional Julia engine; DRModels.jl can also be used directly without R.</p><p>The q=4 phylogenetic bivariate location-scale model has random effects on two mean and two log-scale axes. Its engine uses an augmented-state Laplace approximation with an exact sparse gradient. Sparse factorisation cost depends on the model structure; this is not a package-wide linear-time guarantee.</p><p>Maximum likelihood is the default. Opt-in <code>method = :REML</code> is available on documented model-specific routes. The Gaussian phylogenetic-mean solver also supports <code>algorithm = :em</code>. Wald, profile, and parametric-bootstrap inference have route-specific restrictions; a computed interval does not establish its coverage.</p><p>See the model guides and capability matrix for runnable syntax, accepted combinations, and evidence limits. Measured comparisons with drmTMB retain their run conditions in <code>report/comparison-grid.md</code>; those results apply to the models and data measured, rather than every package workflow.</p>',5)),o(t,{type:"info",class:"source-link",text:"source"},{default:c(()=>[...e[2]||(e[2]=[a("a",{href:"https://github.com/itchyshin/DRModels.jl/blob/966c5f2fbd019b71ef554e1530832294faf257fb/src/DRModels.jl#L1-L27",target:"_blank",rel:"noreferrer"},"source",-1)])]),_:1})])])}const T=i(p,[["render",m]]);export{v as __pageData,T as default};
